  },
  github: {
    grid: 24,
    parts: [["s", "M6.3 3.9 C8 4 9.3 5 10.1 5.8 C11.4 5.5 12.7 5.5 14 5.8 C14.8 5 16.1 4 17.8 3.9 C18.4 5.2 18.4 6.6 18 7.8 C19.3 9 19.8 10.8 19.6 12.6 C19.2 16.6 15.9 19.1 12 19 C8.1 18.9 4.8 16.6 4.5 12.6 C4.3 10.8 4.8 9 6.1 7.8 C5.7 6.6 5.7 5.2 6.3 3.9", 1.1], ["s", "M9.9 19 C9.3 20.3 8 20.9 6.7 20.5", 0.95], ["s", "M14.3 19 C15 20.4 16.4 20.9 17.9 20.3", 0.95]]
  }
